/**
 * Axios 网络请求配置
 * 功能：统一处理网络请求的配置、拦截器和错误处理，添加缓存功能
 */
import axios from "axios";

/**
 * 创建axios实例
 * @property {string} baseURL - API基础地址
 * @property {number} timeout - 请求超时时间（毫秒）
 */
const service = axios.create({
  baseURL: "http://localhost:3000/api",
  // API基础地址
  timeout: 90000 // 请求超时时间（90秒）
});

// 缓存对象
const cache = new Map();
const cacheExpiration = new Map();
const CACHE_DURATION = 5 * 60 * 1000; // 缓存过期时间：5分钟

/**
 * 生成缓存键
 * @param {string} url - 请求URL
 * @param {object} params - 请求参数
 * @returns {string} 缓存键
 */
const generateCacheKey = (url, params) => {
  return `${url}_${JSON.stringify(params)}`;
};

/**
 * 检查缓存是否有效
 * @param {string} key - 缓存键
 * @returns {boolean} 缓存是否有效
 */
const isCacheValid = key => {
  if (!cache.has(key)) return false;
  const expiration = cacheExpiration.get(key);
  return expiration && Date.now() < expiration;
};

/**
 * 请求拦截器
 * 功能：在请求发送前添加认证信息和检查缓存
 */
service.interceptors.request.use(config => {
  // 从localStorage获取token
  const token = localStorage.getItem("token");
  // 如果token存在，添加到请求头
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }

  // 检查是否需要缓存
  if (config.method === "get" && !config.noCache) {
    const cacheKey = generateCacheKey(config.url, config.params);
    if (isCacheValid(cacheKey)) {
      // 返回缓存的数据
      return Promise.resolve({
        data: cache.get(cacheKey),
        status: 200,
        statusText: "OK",
        headers: {},
        config: config
      });
    }
  }
  return config;
}, error => {
  console.error("请求错误:", error);
  return Promise.reject(error);
});

/**
 * 响应拦截器
 * 功能：统一处理响应错误，特别是401认证错误，添加缓存
 */
service.interceptors.response.use(response => {
  // 缓存GET请求的响应
  if (response.config.method === "get" && !response.config.noCache) {
    const cacheKey = generateCacheKey(response.config.url, response.config.params);
    cache.set(cacheKey, response.data);
    cacheExpiration.set(cacheKey, Date.now() + CACHE_DURATION);

    // 清理过期缓存
    setTimeout(() => {
      if (cache.has(cacheKey)) {
        cache.delete(cacheKey);
        cacheExpiration.delete(cacheKey);
      }
    }, CACHE_DURATION);
  }
  return response;
}, error => {
  console.error("响应错误:", error);
  // 处理401错误（未认证或token过期）
  if (error.response && error.response.status === 401) {
    // 清除localStorage中的token和user信息
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    // 跳转到登录页面
    window.location.href = "/login";
  }
  return Promise.reject(error);
});

// 导出axios实例
export default service;

